insert into public.answer_option_translations (option_id, lang, text) values
('af4ae05c-9197-c703-c96a-57c7e7939766', 'de', 'Sie wurden aus dem Lager verbannt'),
('af4ae05c-9197-c703-c96a-57c7e7939766', 'en', 'They were banished from the camp'),
('82e598ca-f8b7-d7ae-75d5-bd0ee3f8b92a', 'de', 'Ein Feuer verzehrte sie auf der Stelle'),
('82e598ca-f8b7-d7ae-75d5-bd0ee3f8b92a', 'en', 'Fire consumed them on the spot'),
('b4ec243d-f3ab-fc1f-5274-5c067d7235bf', 'de', 'Sie ertranken im Roten Meer'),
('b4ec243d-f3ab-fc1f-5274-5c067d7235bf', 'en', 'They drowned in the Red Sea'),
('57701475-05bd-62f1-342c-7fd111fbd0c7', 'de', 'Die Erde tat sich auf und verschlang sie'),
('57701475-05bd-62f1-342c-7fd111fbd0c7', 'en', 'The earth opened and swallowed them'),
('46bb5210-8eb8-d4fa-cd63-c6bb8568aaae', 'de', 'Sie wurde vom Feuer verschlungen'),
('46bb5210-8eb8-d4fa-cd63-c6bb8568aaae', 'en', 'She was swept away by the fire'),
('8901d469-6cc5-1208-8c00-e15dbc409a3c', 'de', 'Sie wurde zu Stein verwandelt'),
('8901d469-6cc5-1208-8c00-e15dbc409a3c', 'en', 'She was turned to stone'),
('e81bc7ca-977e-01f5-a73d-cffe49f8323e', 'de', 'Sie wurde mit Blindheit geschlagen'),
('e81bc7ca-977e-01f5-a73d-cffe49f8323e', 'en', 'She was struck blind'),
('09299e89-2a8f-55ea-a324-dfdb457bc717', 'de', 'Sie wurde zu einer Salzsäule'),
('09299e89-2a8f-55ea-a324-dfdb457bc717', 'en', 'She was turned into a pillar of salt'),
('992175b3-4380-2a89-1dc6-e8f080fe3e81', 'de', 'Er starb und wurde in einem unbekannten Grab begraben'),
('992175b3-4380-2a89-1dc6-e8f080fe3e81', 'en', 'He died and was buried in an unknown grave'),
('7011b949-9b9a-a834-c6ea-720025e7afd5', 'de', 'Er wurde von einem Engel hinweggetragen'),
('7011b949-9b9a-a834-c6ea-720025e7afd5', 'en', 'He was carried away by an angel'),
('1e968d5f-f25d-33a3-f59a-4ab935b708b2', 'de', 'Er schlief ein und erwachte nicht mehr'),
('1e968d5f-f25d-33a3-f59a-4ab935b708b2', 'en', 'He fell asleep and never awoke'),
('1b42bcba-5ac4-5343-9c1f-7c750f52f8b0', 'de', 'Er wurde in einem Wirbelwind in den Himmel emporgehoben'),
('1b42bcba-5ac4-5343-9c1f-7c750f52f8b0', 'en', 'He was taken up to heaven in a whirlwind'),
('89badbc0-3d3d-8125-0a2d-9cdc7bdc233a', 'de', 'Mit Manna, Brot vom Himmel'),
('89badbc0-3d3d-8125-0a2d-9cdc7bdc233a', 'en', 'With manna, bread from heaven'),
('cf99a2fd-5b32-6773-d7e7-f53f8f0c8024', 'de', 'Mit Früchten aus Wüstenoasen'),
('cf99a2fd-5b32-6773-d7e7-f53f8f0c8024', 'en', 'With fruit from desert oases'),
('56f3624c-7b1b-08d1-6e9e-889c991a626c', 'de', 'Mit Fischen aus dem Meer'),
('56f3624c-7b1b-08d1-6e9e-889c991a626c', 'en', 'With fish from the sea'),
('63cb3491-768b-4f96-9fa2-899d283f1826', 'de', 'Mit Getreide, das sie aus Ägypten mitbrachten'),
('63cb3491-768b-4f96-9fa2-899d283f1826', 'en', 'With grain they carried from Egypt'),
('a0570243-f637-d88b-cd4a-4753b8beaa49', 'de', 'Er schwamm wohlbehalten ans Ufer'),
('a0570243-f637-d88b-cd4a-4753b8beaa49', 'en', 'He swam safely to the shore'),
('177095f6-7e67-0b97-7cfd-975c52e4a4b7', 'de', 'Ein großer Fisch verschlang ihn'),
('177095f6-7e67-0b97-7cfd-975c52e4a4b7', 'en', 'A great fish swallowed him'),
('1e5273f4-ecff-ee18-251d-b0a5ff94ed57', 'de', 'Er ertrank und wurde betrauert'),
('1e5273f4-ecff-ee18-251d-b0a5ff94ed57', 'en', 'He drowned and was mourned'),
('164637dc-da88-b8fa-449f-75d024f0d115', 'de', 'Ein vorbeifahrendes Schiff rettete ihn'),
('164637dc-da88-b8fa-449f-75d024f0d115', 'en', 'A passing ship rescued him'),
('cb6d84fd-151c-a6aa-718b-24fd43b1f811', 'de', 'Eine Flut spülte die Mauern fort'),
('cb6d84fd-151c-a6aa-718b-24fd43b1f811', 'en', 'A flood washed the walls away'),
('56c95af6-c6c8-240c-dda2-13556a634421', 'de', 'Die Mauern der Stadt stürzten ein'),
('56c95af6-c6c8-240c-dda2-13556a634421', 'en', 'The walls of the city collapsed'),
('91474263-b9da-2a9f-ae1a-99b3d396c580', 'de', 'Die Stadt ergab sich kampflos'),
('91474263-b9da-2a9f-ae1a-99b3d396c580', 'en', 'The city surrendered without a fight'),
('b99e9384-9bd7-fe48-ac2c-b883772b1608', 'de', 'Die Tore wurden von Spähern geöffnet'),
('b99e9384-9bd7-fe48-ac2c-b883772b1608', 'en', 'The gates were opened by spies'),
('4adb830c-a1a9-4d7f-f8c9-6cc2c1f18100', 'de', 'Er steuerte das Boot sicher ans Ufer'),
('4adb830c-a1a9-4d7f-f8c9-6cc2c1f18100', 'en', 'He steered the boat safely to shore'),
('b4d98fcf-d7b7-51aa-8439-ff98a8b64d69', 'de', 'Er gebot dem Wind und den Wellen Einhalt'),
('b4d98fcf-d7b7-51aa-8439-ff98a8b64d69', 'en', 'He rebuked the wind and the waves'),
('23913644-21a7-ecd6-eefb-793fa92562a7', 'de', 'Er hieß die Jünger, kräftiger zu rudern'),
('23913644-21a7-ecd6-eefb-793fa92562a7', 'en', 'He told the disciples to row harder'),
('7de3c76d-3ac8-e5d4-1b5d-0d9e50b8434e', 'de', 'Er betete, bis der Sturm vorüberzog'),
('7de3c76d-3ac8-e5d4-1b5d-0d9e50b8434e', 'en', 'He prayed until the storm passed'),
('33114231-cef5-0d10-4008-76237c87e099', 'de', 'Sie wurden aus der Gemeinde ausgestoßen'),
('33114231-cef5-0d10-4008-76237c87e099', 'en', 'They were cast out of the church'),
('9b5865d4-15b6-a16d-d26d-60ae8794200c', 'de', 'Sie fielen tot zu Boden'),
('9b5865d4-15b6-a16d-d26d-60ae8794200c', 'en', 'They fell down dead'),
('e3303965-08cb-d343-9e5d-43fdf8dc863e', 'de', 'Sie wurden mit Aussatz geschlagen'),
('e3303965-08cb-d343-9e5d-43fdf8dc863e', 'en', 'They were struck with leprosy'),
('c247b5cc-182e-da1b-273d-109415978823', 'de', 'Sie wurden von den Aposteln eingekerkert'),
('c247b5cc-182e-da1b-273d-109415978823', 'en', 'They were imprisoned by the apostles'),
('91650881-c697-b5e5-67f3-1a64a2269a9d', 'de', 'Er ließ ihn erst als Tagelöhner arbeiten'),
('91650881-c697-b5e5-67f3-1a64a2269a9d', 'en', 'He made him work as a hired servant first'),
('646b66be-9763-b207-3f3d-66a1de638b72', 'de', 'Er lief ihm entgegen und richtete ein Fest aus'),
('646b66be-9763-b207-3f3d-66a1de638b72', 'en', 'He ran to him and held a feast'),
('921f4f3b-c268-3211-bda7-1ba2473095fb', 'de', 'Er forderte das vergeudete Geld zurück'),
('921f4f3b-c268-3211-bda7-1ba2473095fb', 'en', 'He demanded the wasted money back'),
('b1e15ed7-0588-0e34-29f1-468c393dfdeb', 'de', 'Er wies ihn zornig ab'),
('b1e15ed7-0588-0e34-29f1-468c393dfdeb', 'en', 'He turned him away in anger'),
('02d17fdb-b03e-6066-e3da-269641edba74', 'de', 'Eine Wolken- und Feuersäule'),
('02d17fdb-b03e-6066-e3da-269641edba74', 'en', 'A pillar of cloud and fire'),
('d6c9c015-e104-ac34-e5ed-4a5f7acb674c', 'de', 'Einen hellen Morgenstern'),
('d6c9c015-e104-ac34-e5ed-4a5f7acb674c', 'en', 'A bright morning star'),
('ef345921-4768-4144-05ba-16ed7d16cc12', 'de', 'Einen Regenbogen in den Wolken'),
('ef345921-4768-4144-05ba-16ed7d16cc12', 'en', 'A rainbow in the clouds'),
('9ea3f185-486f-90f6-de6e-833993bb4c58', 'de', 'Eine Taube mit einem Ölzweig'),
('9ea3f185-486f-90f6-de6e-833993bb4c58', 'en', 'A dove with an olive branch'),
('ab0b197c-41ba-717a-5997-192fc1dd2144', 'de', 'Er vertrieb die Reichen aus der Stadt'),
('ab0b197c-41ba-717a-5997-192fc1dd2144', 'en', 'He drove the rich out of the city'),
('30956f23-25d8-6e04-260c-7256ef0d3850', 'de', 'Er übergab die Reichen den persischen Behörden'),
('30956f23-25d8-6e04-260c-7256ef0d3850', 'en', 'He handed the rich over to the Persian authorities'),
('12daf490-1e97-4e08-986c-c312f7421d21', 'de', 'Er ließ sie die Wucherzinsen und verpfändeten Güter zurückgeben'),
('12daf490-1e97-4e08-986c-c312f7421d21', 'en', 'He made them return the usury and pledged goods'),
('6ac89055-803c-7515-9d69-9071b0412996', 'de', 'Er erhob eine neue Steuer von allen Bürgern'),
('6ac89055-803c-7515-9d69-9071b0412996', 'en', 'He levied a new tax on all citizens'),
('12a53594-5436-f0b1-d638-c77193314358', 'de', 'Ein großes Schwert in seiner Hand'),
('12a53594-5436-f0b1-d638-c77193314358', 'en', 'A great sword in his hand'),
('ef6ebd99-321a-9808-c840-1c3f9c5c1d06', 'de', 'Eine brennende Fackel in seiner Hand'),
('ef6ebd99-321a-9808-c840-1c3f9c5c1d06', 'en', 'A burning torch in his hand'),
('750be662-8ab8-40ae-bac6-5a2d09fce571', 'de', 'Einen Bogen in seiner Hand'),
('750be662-8ab8-40ae-bac6-5a2d09fce571', 'en', 'A bow in his hand'),
('e8b0cd25-231c-e003-ff43-d9f376853c61', 'de', 'Eine Waage in seiner Hand'),
('e8b0cd25-231c-e003-ff43-d9f376853c61', 'en', 'A pair of scales in his hand'),
('f148753a-2b63-9b68-3680-3d42b41f1655', 'de', 'Eine Hungersnot, die das Land traf'),
('f148753a-2b63-9b68-3680-3d42b41f1655', 'en', 'A famine that struck the land'),
('7c79906a-f393-66bb-9cab-9e772d8fec86', 'de', 'Sein Hochmut über den Tempelbau'),
('7c79906a-f393-66bb-9cab-9e772d8fec86', 'en', 'His pride over building the temple'),
('a0dc4cc8-e743-5a6e-2185-68be60092061', 'de', 'Seine vielen fremden Frauen verleiteten ihn zu anderen Göttern'),
('a0dc4cc8-e743-5a6e-2185-68be60092061', 'en', 'His many foreign wives turned him to other gods'),
('f066cd27-a1da-4cd3-5beb-f210c9f4a732', 'de', 'Der Verlust seines Reichtums durch Krieg'),
('f066cd27-a1da-4cd3-5beb-f210c9f4a732', 'en', 'The loss of his wealth through war'),
('4bba3f25-5cf4-6a97-7b5b-4ea875a623cb', 'de', 'Gott ist Liebe, und wer in der Liebe bleibt, bleibt in Gott'),
('4bba3f25-5cf4-6a97-7b5b-4ea875a623cb', 'en', 'God is love, and whoever abides in love abides in God'),
('0a3ee503-826f-e500-93ce-77f6d00a4b40', 'de', 'Gott ist Liebe, die alle Schuld vergisst'),
('0a3ee503-826f-e500-93ce-77f6d00a4b40', 'en', 'God is love that forgets all guilt'),
('f65827a7-619d-c291-b452-c800330ce569', 'de', 'Gott ist Liebe nur für die Gerechten'),
('f65827a7-619d-c291-b452-c800330ce569', 'en', 'God is love only for the righteous'),
('7fa8be0d-a6f7-8253-73fb-59e5089976c9', 'de', 'Gott ist Liebe, die kein Gebot kennt'),
('7fa8be0d-a6f7-8253-73fb-59e5089976c9', 'en', 'God is love that knows no commandment'),
('8f81012e-1608-19dd-0a1d-623c109fd3e5', 'de', 'Etwa dreitausend Seelen'),
('8f81012e-1608-19dd-0a1d-623c109fd3e5', 'en', 'About three thousand souls'),
('04959098-847a-e7f3-714b-da17bad30174', 'de', 'Etwa fünftausend Männer'),
('04959098-847a-e7f3-714b-da17bad30174', 'en', 'About five thousand men'),
('7ac0a3ac-85b8-beb2-11db-9faad681aecb', 'de', 'Etwa siebzig Älteste'),
('7ac0a3ac-85b8-beb2-11db-9faad681aecb', 'en', 'About seventy elders'),
('6ccf3f59-8989-5259-9ab8-8467260cac9a', 'de', 'Etwa hundertzwanzig Jünger'),
('6ccf3f59-8989-5259-9ab8-8467260cac9a', 'en', 'About one hundred and twenty disciples'),
('df7cdfac-8765-d0af-eea7-77f11e08d282', 'de', 'Sie schwiegen voller Furcht'),
('df7cdfac-8765-d0af-eea7-77f11e08d282', 'en', 'They kept silent in fear'),
('68532ab2-3579-b051-30ce-86e424d558d2', 'de', 'Sie entsetzten sich über die Vollmacht seiner Lehre'),
('68532ab2-3579-b051-30ce-86e424d558d2', 'en', 'They were astonished at the authority of his teaching'),
('b288f2a2-6b28-57ca-5ca9-8afd223ff1f3', 'de', 'Sie verließen unwillig das Haus'),
('b288f2a2-6b28-57ca-5ca9-8afd223ff1f3', 'en', 'They left the place unwilling'),
('5659d16d-112a-8581-3b0e-c5006cbd9214', 'de', 'Sie warfen Steine nach ihm'),
('5659d16d-112a-8581-3b0e-c5006cbd9214', 'en', 'They threw stones at him'),
('1322d66c-2eda-cc4e-e4b8-2692051261d5', 'de', 'Dass der König zuerst Haman absetzte'),
('1322d66c-2eda-cc4e-e4b8-2692051261d5', 'en', 'That the king first depose Haman'),
('6c8cfb88-7d5b-75c4-9514-adb47907dfed', 'de', 'Dass man ihr eine Leibwache zur Seite stellte'),
('6c8cfb88-7d5b-75c4-9514-adb47907dfed', 'en', 'That a bodyguard be placed at her side'),
('4de6567d-b66f-8165-b40b-9fb31f3b9b25', 'de', 'Dass die Juden in Susa drei Tage mit ihr fasteten'),
('4de6567d-b66f-8165-b40b-9fb31f3b9b25', 'en', 'That the Jews in Susa fast with her for three days'),
('12f4522b-a5e6-6bc8-27fc-a10718f728e1', 'de', 'Dass Mordechai ein Heer um die Stadt sammelte'),
('12f4522b-a5e6-6bc8-27fc-a10718f728e1', 'en', 'That Mordecai gather an army around the city'),
('5fef1aac-d34c-7eb1-bc6e-1c481883f667', 'de', 'Zu hüten und zu weiden wie ein Hirte'),
('5fef1aac-d34c-7eb1-bc6e-1c481883f667', 'en', 'To tend and feed like a shepherd'),
('2459dc6f-fa28-20e4-6481-e28885791efa', 'de', 'Zu säen und zu ernten in fremdem Land'),
('2459dc6f-fa28-20e4-6481-e28885791efa', 'en', 'To sow and reap in a foreign land'),
('fea91270-6060-5c95-9ec8-66eec171f63c', 'de', 'Zu richten und zu krönen wie ein König'),
('fea91270-6060-5c95-9ec8-66eec171f63c', 'en', 'To judge and crown like a king'),
('e3b721cd-de98-b006-8ac7-017442e035cc', 'de', 'Auszureißen und einzureißen, zu bauen und zu pflanzen'),
('e3b721cd-de98-b006-8ac7-017442e035cc', 'en', 'To uproot and tear down, to build and to plant'),
('662595c8-bb2d-6c12-b49e-47c713b7848a', 'de', 'Eine Flutung der Felder'),
('662595c8-bb2d-6c12-b49e-47c713b7848a', 'en', 'A flooding of the fields'),
('de56b063-0ac0-5203-575f-cc585964011a', 'de', 'Einen Hinterhalt hinter der Stadt'),
('de56b063-0ac0-5203-575f-cc585964011a', 'en', 'An ambush behind the city'),
('99655de2-64ad-6103-8e99-1e1c7972eb87', 'de', 'Einen nächtlichen Sturmangriff'),
('99655de2-64ad-6103-8e99-1e1c7972eb87', 'en', 'A night assault'),
('b0b8872f-a225-fda1-b810-4771a776cc3e', 'de', 'Eine lange Belagerung'),
('b0b8872f-a225-fda1-b810-4771a776cc3e', 'en', 'A long siege'),
('7825ba2f-3b88-ad23-2a2e-c1f5eaf23efd', 'de', 'Er wollte sieben Jahre fasten'),
('7825ba2f-3b88-ad23-2a2e-c1f5eaf23efd', 'en', 'He would fast for seven years'),
('218a04f1-2f73-e51f-d606-d28431a212be', 'de', 'Er wollte opfern, was ihm zuerst aus dem Haus entgegenkäme'),
('218a04f1-2f73-e51f-d606-d28431a212be', 'en', 'He would sacrifice whatever first came out to meet him'),
('a114b2ff-0573-9ac3-ea5f-25fb43afdf19', 'de', 'Er wollte einen Altar aus reinem Gold bauen'),
('a114b2ff-0573-9ac3-ea5f-25fb43afdf19', 'en', 'He would build an altar of pure gold'),
('8b91db91-8236-2de5-6dc1-34f369f15ed9', 'de', 'Er wollte die halbe Beute dem Heiligtum geben'),
('8b91db91-8236-2de5-6dc1-34f369f15ed9', 'en', 'He would give half the spoil to the sanctuary'),
('e7a0356e-7c50-ffe7-64ed-f8e9921719f0', 'de', 'Ein Stein, der sich ohne Menschenhand löste'),
('e7a0356e-7c50-ffe7-64ed-f8e9921719f0', 'en', 'A stone cut out without human hands'),
('304231bb-f2cb-3fbf-e120-833dfa5e85b7', 'de', 'Ein Schwert eines Riesen'),
('304231bb-f2cb-3fbf-e120-833dfa5e85b7', 'en', 'The sword of a giant'),
('0138ea0d-7f21-1df0-4793-430db9b02e6f', 'de', 'Ein Blitz vom Himmel'),
('0138ea0d-7f21-1df0-4793-430db9b02e6f', 'en', 'A bolt of lightning from heaven'),
('3525246a-1861-c26b-05bc-9446b66e8e4c', 'de', 'Ein gewaltiger Sturmwind'),
('3525246a-1861-c26b-05bc-9446b66e8e4c', 'en', 'A mighty storm wind'),
('5211e3f9-3365-d184-6c31-e797933bcd67', 'de', 'Kehre zurück zu deinem Handwerk'),
('5211e3f9-3365-d184-6c31-e797933bcd67', 'en', 'Return to your trade'),
('905552be-eece-4365-6c9c-60906afe8754', 'de', 'Schweige über das, was geschah'),
('905552be-eece-4365-6c9c-60906afe8754', 'en', 'Keep silent about what happened'),
('c69932ee-a355-de1b-ea21-5cce13cee806', 'de', 'Verkaufe die Fische auf dem Markt'),
('c69932ee-a355-de1b-ea21-5cce13cee806', 'en', 'Sell the fish at the market'),
('34b95240-d985-c8e8-2fb4-6c53c68b7cee', 'de', 'Von nun an wirst du Menschen fangen'),
('34b95240-d985-c8e8-2fb4-6c53c68b7cee', 'en', 'From now on you will catch people'),
('a12cc1f3-ec0b-4376-cc56-3ed870a50b2c', 'de', 'Des Bundes und des Gesetzes'),
('a12cc1f3-ec0b-4376-cc56-3ed870a50b2c', 'en', 'Of the covenant and the law'),
('435adfaa-d731-bdf1-5d55-ff84e1d70b7b', 'de', 'Des Herrn der Heerscharen allein'),
('435adfaa-d731-bdf1-5d55-ff84e1d70b7b', 'en', 'Of the Lord of hosts alone'),
('a9202df3-96ed-800f-32be-e86034f8e854', 'de', 'Des Messias und seiner Propheten'),
('a9202df3-96ed-800f-32be-e86034f8e854', 'en', 'Of the Messiah and his prophets'),
('10c8c625-1f01-2d59-6ac5-0fbf56713fd8', 'de', 'Des Vaters, des Sohnes und des Heiligen Geistes'),
('10c8c625-1f01-2d59-6ac5-0fbf56713fd8', 'en', 'Of the Father, the Son, and the Holy Spirit'),
('4c05a200-ff07-9ae3-2b09-7e96891e670f', 'de', 'Sein Gott habe einen Engel gesandt, der die Rachen der Löwen verschloss'),
('4c05a200-ff07-9ae3-2b09-7e96891e670f', 'en', 'His God had sent an angel who shut the lions'' mouths'),
('a554e50a-1891-8313-6284-ae2f4961d23f', 'de', 'Er sei verletzt, aber lebendig'),
('a554e50a-1891-8313-6284-ae2f4961d23f', 'en', 'He was wounded but alive'),
('a7030953-c618-7c4f-4733-9141ae3ad982', 'de', 'Die Löwen seien eingeschlafen'),
('a7030953-c618-7c4f-4733-9141ae3ad982', 'en', 'The lions had fallen asleep'),
('9379dcda-8015-8c6b-2c48-eaf51ef4cea7', 'de', 'Er habe sich versteckt gehalten'),
('9379dcda-8015-8c6b-2c48-eaf51ef4cea7', 'en', 'He had kept himself hidden'),
('4c850bd4-d316-3493-81c0-9617bd6f13a8', 'de', 'Er ließ Brot vom Himmel fallen'),
('4c850bd4-d316-3493-81c0-9617bd6f13a8', 'en', 'He made bread fall from heaven'),
('cca4dc28-39ff-967b-cb2d-21200ef24db0', 'de', 'Er gab ihr Silber aus dem Tempelschatz'),
('cca4dc28-39ff-967b-cb2d-21200ef24db0', 'en', 'He gave her silver from the temple treasury'),
('b1ff3e40-39bd-520d-d9a9-f5e27bba9a71', 'de', 'Ihr Krug Öl füllte viele geliehene Gefäße'),
('b1ff3e40-39bd-520d-d9a9-f5e27bba9a71', 'en', 'Her jar of oil filled many borrowed vessels'),
('0831111c-72ec-ee97-a389-82c3a9c8fd89', 'de', 'Er erließ ihr die Schuld beim König'),
('0831111c-72ec-ee97-a389-82c3a9c8fd89', 'en', 'He cancelled her debt with the king'),
('159096ef-3941-03b5-ee5e-b1c9ac0b8d42', 'de', 'Wenn eure Sünde gleich blutrot ist, soll sie schneeweiß werden'),
('159096ef-3941-03b5-ee5e-b1c9ac0b8d42', 'en', 'Though your sins are like scarlet, they shall be white as snow'),
('7aaecfd0-4785-6fa1-8c8f-3fd567ff5500', 'de', 'Wenn eure Sünde gleich alt ist, soll sie vergessen werden'),
('7aaecfd0-4785-6fa1-8c8f-3fd567ff5500', 'en', 'Though your sins are old, they shall be forgotten'),
('4386b8ee-6020-7d5e-db86-40577ebb841f', 'de', 'Wenn eure Sünde gleich schwer ist, soll sie weggetragen werden'),
('4386b8ee-6020-7d5e-db86-40577ebb841f', 'en', 'Though your sins are heavy, they shall be carried off'),
('b58982d7-3432-d9c4-2b55-e700ace9257e', 'de', 'Wenn eure Sünde gleich tief ist, soll sie versenkt werden'),
('b58982d7-3432-d9c4-2b55-e700ace9257e', 'en', 'Though your sins are deep, they shall be sunk away'),
('8df84ae3-b6cf-3c7a-b980-9ee5a38efb90', 'de', 'Er wurde von Soldaten verhaftet'),
('8df84ae3-b6cf-3c7a-b980-9ee5a38efb90', 'en', 'He was arrested by soldiers'),
('0189d7d1-e9f8-b096-3ea7-ad6bb132cba8', 'de', 'Er kehrte mit dem Kämmerer nach Äthiopien'),
('0189d7d1-e9f8-b096-3ea7-ad6bb132cba8', 'en', 'He returned to Ethiopia with the eunuch'),
('496b929e-97cd-dec0-614a-5a4314841e7e', 'de', 'Er blieb am Wasser zurück'),
('496b929e-97cd-dec0-614a-5a4314841e7e', 'en', 'He stayed behind at the water'),
('0e4c48fb-8513-a003-f12d-e3a3ef5394f9', 'de', 'Der Geist des Herrn entrückte ihn, und er wurde in Aschdod gefunden'),
('0e4c48fb-8513-a003-f12d-e3a3ef5394f9', 'en', 'The Spirit of the Lord caught him away, and he was found at Azotus'),
('0487dc8d-df4b-dbfd-1b2e-a79ddc248178', 'de', 'Das Versäumen der Wallfahrten'),
('0487dc8d-df4b-dbfd-1b2e-a79ddc248178', 'en', 'Failing to make pilgrimages'),
('b2947bb4-ac84-d64b-5a49-df5cd35fe4eb', 'de', 'Die Unterdrückung der Armen und das Unrecht'),
('b2947bb4-ac84-d64b-5a49-df5cd35fe4eb', 'en', 'The oppression of the poor and injustice'),
('3f1df9c0-aa86-ebde-9004-74aae9edf3de', 'de', 'Die Heirat mit Fremden'),
('3f1df9c0-aa86-ebde-9004-74aae9edf3de', 'en', 'Marriage with foreigners'),
('54b94759-c0ab-8bd7-114d-cd5d87d6158b', 'de', 'Die Vernachlässigung der Beschneidung'),
('54b94759-c0ab-8bd7-114d-cd5d87d6158b', 'en', 'The neglect of circumcision'),
('96ad7897-50d1-0747-334e-53e44f36d6f3', 'de', 'Gold, Bronze, Holz, Stein und Lehm'),
('96ad7897-50d1-0747-334e-53e44f36d6f3', 'en', 'Gold, bronze, wood, stone, and clay'),
('e3834c8e-9f39-1d99-332f-e6e3539558a8', 'de', 'Silber, Gold, Eisen, Erz und Stein'),
('e3834c8e-9f39-1d99-332f-e6e3539558a8', 'en', 'Silver, gold, iron, bronze, and stone'),
('d7b4f9ad-8ba0-c88a-06fd-bd967f803ccb', 'de', 'Eisen, Erz, Silber, Gold und Ton'),
('d7b4f9ad-8ba0-c88a-06fd-bd967f803ccb', 'en', 'Iron, bronze, silver, gold, and clay'),
('72c0f965-fd50-1226-0dbd-df9d7aa6719a', 'de', 'Gold, Silber, Erz, Eisen und Eisen mit Ton'),
('72c0f965-fd50-1226-0dbd-df9d7aa6719a', 'en', 'Gold, silver, bronze, iron, and iron mixed with clay'),
('16b25333-3d2f-3b1b-2df4-30afae5674f6', 'de', 'Die Asche eines Ziegenbocks'),
('16b25333-3d2f-3b1b-2df4-30afae5674f6', 'en', 'The ashes of a male goat'),
('be61a158-08bf-fab6-a492-46140cc32711', 'de', 'Die Asche eines weißen Lammes'),
('be61a158-08bf-fab6-a492-46140cc32711', 'en', 'The ashes of a white lamb'),
('a0e7c0a7-c9bf-3436-a695-fbf9fc4299b6', 'de', 'Die Asche einer roten, makellosen Kuh'),
('a0e7c0a7-c9bf-3436-a695-fbf9fc4299b6', 'en', 'The ashes of a red, unblemished cow'),
('9fc85e3d-c17c-2081-e83e-67c6e86d112e', 'de', 'Die Asche eines schwarzen Stieres'),
('9fc85e3d-c17c-2081-e83e-67c6e86d112e', 'en', 'The ashes of a black bull'),
('46940331-038e-9f5a-ee3c-17837d760842', 'de', 'Er wurde von seinen eigenen Männern verraten'),
('46940331-038e-9f5a-ee3c-17837d760842', 'en', 'He was betrayed by his own men'),
('96eb378c-fc50-8974-7e9c-6b97237c8f7b', 'de', 'Er stürzte mit dem Pferd in einen Graben'),
('96eb378c-fc50-8974-7e9c-6b97237c8f7b', 'en', 'He fell with his horse into a ditch'),
('25f557c6-032c-746f-a207-e18203ae008a', 'de', 'Sein Haupt verfing sich in den Ästen einer großen Eiche, während sein Maultier weiterlief'),
('25f557c6-032c-746f-a207-e18203ae008a', 'en', 'His head got caught in the branches of a great oak while his mule went on'),
('1bd4ba99-f30d-4447-5267-ac52d4e98028', 'de', 'Er verlief sich in der Wüste ohne Wasser'),
('1bd4ba99-f30d-4447-5267-ac52d4e98028', 'en', 'He got lost in the desert without water'),
('4b37cb8c-eea2-e3ab-7f1e-aa6fa89fcd1a', 'de', 'Durch das Feuer vom Himmel'),
('4b37cb8c-eea2-e3ab-7f1e-aa6fa89fcd1a', 'en', 'By fire from heaven'),
('a1b821f5-5ad2-6f0e-c1e7-cca25609de7f', 'de', 'Durch ein Erdbeben in der Nacht'),
('a1b821f5-5ad2-6f0e-c1e7-cca25609de7f', 'en', 'By an earthquake in the night'),
('a780a0da-a5ae-4ea4-18d7-a0b5340443fe', 'de', 'Durch die Belagerung mit Kriegsgerät'),
('a780a0da-a5ae-4ea4-18d7-a0b5340443fe', 'en', 'By a siege with war machines'),
('d39435cc-df84-a615-944b-592622c50d38', 'de', 'Durch den Glauben, nachdem man sie umzogen hatte'),
('d39435cc-df84-a615-944b-592622c50d38', 'en', 'By faith, after they had been encircled'),
('f600bb9b-82cf-dd58-c725-b67f190febc7', 'de', 'Mit dem guten Hirten, der bleibt'),
('f600bb9b-82cf-dd58-c725-b67f190febc7', 'en', 'With the good shepherd who stays'),
('6368259d-81da-1574-8970-de6e511cb71c', 'de', 'Mit dem Sämann auf dem Feld'),
('6368259d-81da-1574-8970-de6e511cb71c', 'en', 'With the sower in the field'),
('d8cd09c9-13eb-c29f-e8c8-ae3f24c2fac3', 'de', 'Mit dem Wächter an der Tür'),
('d8cd09c9-13eb-c29f-e8c8-ae3f24c2fac3', 'en', 'With the watchman at the door'),
('ef353cc3-ea4c-dac5-22ba-1a44020d641d', 'de', 'Mit dem treuen Knecht im Haus'),
('ef353cc3-ea4c-dac5-22ba-1a44020d641d', 'en', 'With the faithful servant in the house'),
('a767fb3f-c2e7-edaf-cd7a-4aff9b1eb652', 'de', 'Er ließ die Jünger ans Ufer rudern'),
('a767fb3f-c2e7-edaf-cd7a-4aff9b1eb652', 'en', 'He had the disciples row to shore'),
('c7d7e8c8-1b96-e247-3d2e-0d61cf99196d', 'de', 'Er schwieg, bis der Sturm vorüberzog'),
('c7d7e8c8-1b96-e247-3d2e-0d61cf99196d', 'en', 'He stayed silent until the storm passed'),
('d6182392-9b83-4387-ecde-c31242f9fd9c', 'de', 'Er warf die Ladung über Bord'),
('d6182392-9b83-4387-ecde-c31242f9fd9c', 'en', 'He threw the cargo overboard'),
('3e5830f1-8229-acec-efb8-027ac0c7ee13', 'de', 'Er gebot dem Wind und den Wellen, und es wurde still'),
('3e5830f1-8229-acec-efb8-027ac0c7ee13', 'en', 'He rebuked the wind and the waves, and it became calm'),
('7b545b17-8ac2-3f0e-b2d2-226b123e1baf', 'de', 'Sie fingen eine so große Menge, dass die Netze zerrissen'),
('7b545b17-8ac2-3f0e-b2d2-226b123e1baf', 'en', 'They caught such a quantity that the nets began to tear'),
('3785cb50-0044-f255-c656-640ac38becdb', 'de', 'Sie fingen nur einen einzigen großen Fisch'),
('3785cb50-0044-f255-c656-640ac38becdb', 'en', 'They caught only one single large fish'),
('5c2d178a-c223-1f45-a32d-8fc57eacb5cf', 'de', 'Die Netze blieben den ganzen Tag leer'),
('5c2d178a-c223-1f45-a32d-8fc57eacb5cf', 'en', 'The nets stayed empty all day'),
('af12a9dc-02f9-110e-040b-4cf02582fc88', 'de', 'Ein Sturm trieb sie ans Ufer zurück'),
('af12a9dc-02f9-110e-040b-4cf02582fc88', 'en', 'A storm drove them back to shore'),
('4631485f-0e93-32af-1f88-40b7914c8de7', 'de', 'Salome aus Galiläa'),
('4631485f-0e93-32af-1f88-40b7914c8de7', 'en', 'Salome from Galilee'),
('57b2e279-b515-f2b0-b161-1edb749f89ac', 'de', 'Maria von Magdala'),
('57b2e279-b515-f2b0-b161-1edb749f89ac', 'en', 'Mary Magdalene'),
('ebe2ea31-3975-f53d-0f92-a17e3e57a5f6', 'de', 'Johanna, der Frau des Chuza'),
('ebe2ea31-3975-f53d-0f92-a17e3e57a5f6', 'en', 'Joanna, the wife of Chuza'),
('1dab2eb4-59b9-bb60-524b-6df9025cf409', 'de', 'Maria, der Mutter Jesu'),
('1dab2eb4-59b9-bb60-524b-6df9025cf409', 'en', 'Mary, the mother of Jesus'),
('25c65f1f-2714-57cc-6cce-b0fcc2ac32a7', 'de', 'Niemand verstand ein Wort'),
('25c65f1f-2714-57cc-6cce-b0fcc2ac32a7', 'en', 'No one understood a word'),
('d56ebbc4-3a7b-5cb5-8d39-4441586014f6', 'de', 'Sie hörten nur Gesang'),
('d56ebbc4-3a7b-5cb5-8d39-4441586014f6', 'en', 'They heard only singing'),
('29fedf85-764f-00fe-2803-e6dc3f91c716', 'de', 'Jeder hörte sie in seiner eigenen Muttersprache reden'),
('29fedf85-764f-00fe-2803-e6dc3f91c716', 'en', 'Each heard them speaking in his own native language'),
('78315a34-711c-f67c-959a-4a7a35ea691b', 'de', 'Alle hörten nur Hebräisch'),
('78315a34-711c-f67c-959a-4a7a35ea691b', 'en', 'All heard only Hebrew'),
('b3d69687-e15b-f018-f8f3-38d180f0c8ec', 'de', 'Steh auf, HERR, dass deine Feinde zerstreut werden'),
('b3d69687-e15b-f018-f8f3-38d180f0c8ec', 'en', 'Arise, O LORD, let your enemies be scattered'),
('de5abd29-653a-1868-660b-34ee3f7f5b71', 'de', 'Der HERR segne dich und behüte dich'),
('de5abd29-653a-1868-660b-34ee3f7f5b71', 'en', 'The LORD bless you and keep you'),
('b2a4527a-2b15-3ae0-feeb-e4355e9d34f2', 'de', 'Höre, Israel, der HERR ist einer'),
('b2a4527a-2b15-3ae0-feeb-e4355e9d34f2', 'en', 'Hear, O Israel, the LORD is one'),
('15a77782-e917-6f51-b2a6-20214db04159', 'de', 'Heilig, heilig, heilig ist der HERR'),
('15a77782-e917-6f51-b2a6-20214db04159', 'en', 'Holy, holy, holy is the LORD'),
('28865bf9-f1fd-aeb9-b170-53e382612f31', 'de', 'Er sah ganz Israel zerstreut wie Schafe ohne Hirten'),
('28865bf9-f1fd-aeb9-b170-53e382612f31', 'en', 'He saw all Israel scattered like sheep without a shepherd'),
('d90bd4a8-464c-134a-4f9e-3262fc9c87e5', 'de', 'Er verkündete einen glänzenden Sieg'),
('d90bd4a8-464c-134a-4f9e-3262fc9c87e5', 'en', 'He proclaimed a glorious victory'),
('700ad0a8-5b91-45ee-31a7-74ee56efaa0d', 'de', 'Er weissagte einen schnellen Frieden'),
('700ad0a8-5b91-45ee-31a7-74ee56efaa0d', 'en', 'He prophesied a swift peace'),
('76711c73-fd8d-9dbb-c6c8-3c6977383bc5', 'de', 'Er sah die Stadt in Flammen aufgehen'),
('76711c73-fd8d-9dbb-c6c8-3c6977383bc5', 'en', 'He saw the city going up in flames'),
('ae986ce1-8bb5-a4c0-c3fa-4aec702df4a1', 'de', 'Durch eigene Klugheit'),
('ae986ce1-8bb5-a4c0-c3fa-4aec702df4a1', 'en', 'By one''s own cleverness'),
('5543fcef-16af-8d1e-68e9-930c89c0e81f', 'de', 'Durch Erneuerung des Sinnes'),
('5543fcef-16af-8d1e-68e9-930c89c0e81f', 'en', 'By the renewal of the mind'),
('fd891e47-6f3f-4a60-6409-6cbfce495848', 'de', 'Durch Anpassung an die Welt'),
('fd891e47-6f3f-4a60-6409-6cbfce495848', 'en', 'By conformity to the world'),
('fc0e978e-19f1-4328-906c-40719a86a745', 'de', 'Durch Werke des Gesetzes'),
('fc0e978e-19f1-4328-906c-40719a86a745', 'en', 'By works of the law'),
('11e0e578-4479-df0f-3cd6-7fb657d93d52', 'de', 'Verzicht auf alle Opfer'),
('11e0e578-4479-df0f-3cd6-7fb657d93d52', 'en', 'Abstaining from all sacrifices'),
