('4907408b-6295-5c7c-a8c4-5e098c355a25', 'en', 'The sailors threw him into the sea'),
('20fdfd33-13b3-cf58-8414-770f85ae24ea', 'de', 'Sauls abtrünnige Soldaten'),
('20fdfd33-13b3-cf58-8414-770f85ae24ea', 'en', 'Saul''s deserting soldiers'),
('7b0808bb-cf17-1271-d753-905696ed6800', 'de', 'Bedrängte, Verschuldete und Verbitterte'),
('7b0808bb-cf17-1271-d753-905696ed6800', 'en', 'The distressed, the indebted and the discontented'),
('5e448212-b03a-6943-e0e8-32687c06f44c', 'de', 'Die Ältesten von Juda'),
('5e448212-b03a-6943-e0e8-32687c06f44c', 'en', 'The elders of Judah'),
('30a024c9-c705-25ef-40dc-fcc034824cfc', 'de', 'Die Priester aus Nob'),
('30a024c9-c705-25ef-40dc-fcc034824cfc', 'en', 'The priests from Nob'),
