('484035a9-f86f-83ee-ea34-228a3d5497ad', 'de', '… wird dennoch reich gesegnet'),
('484035a9-f86f-83ee-ea34-228a3d5497ad', 'en', '… will still be richly blessed'),
('406c3b85-7187-a664-5d42-d1e7c0ed4bc0', 'de', 'Dagon, nach dem Gott der Feinde'),
('406c3b85-7187-a664-5d42-d1e7c0ed4bc0', 'en', 'Dagon, after the enemies'' god'),
('47febde9-be38-2a06-a948-649acb9d82b6', 'de', 'Samuel, nach dem Propheten'),
('47febde9-be38-2a06-a948-649acb9d82b6', 'en', 'Samuel, after the prophet'),
('b7d1a810-47c3-f251-ed5b-2a84a641a52d', 'de', 'Eben-Eser, nach dem Schlachtort'),
('b7d1a810-47c3-f251-ed5b-2a84a641a52d', 'en', 'Ebenezer, after the battle site'),
