('cf8bc9c1-15cd-a790-64b0-ee70a92073a0', 'de', 'Ich will sie aus der Macht des Todes erlösen'),
('cf8bc9c1-15cd-a790-64b0-ee70a92073a0', 'en', 'I will ransom them from the power of death'),
('671f5429-219b-13da-e8c6-34770caeb13a', 'de', 'Komm zu mir an einem anderen Tag'),
('671f5429-219b-13da-e8c6-34770caeb13a', 'en', 'Come to me on another day'),
('4d88c296-89ab-0f7b-b5f2-aa811c0b06dd', 'de', 'Ich habe nötig, von dir getauft zu werden'),
('4d88c296-89ab-0f7b-b5f2-aa811c0b06dd', 'en', 'I need to be baptized by you'),
('7547b6aa-3ea9-4174-9d19-9cea4e42a43b', 'de', 'Ich kenne diesen Mann nicht'),
('7547b6aa-3ea9-4174-9d19-9cea4e42a43b', 'en', 'I do not know this man'),
('bdd9478c-f3ed-4a2f-1c7e-fabc1d86e838', 'de', 'Du musst zuerst Buße tun'),
('bdd9478c-f3ed-4a2f-1c7e-fabc1d86e838', 'en', 'You must first repent'),
('2c999e82-b848-169c-ce8b-bfb623e0f455', 'de', 'Doëg, den Edomiter'),
('2c999e82-b848-169c-ce8b-bfb623e0f455', 'en', 'Doeg the Edomite'),
('925ca864-222a-e950-020f-8630cb54f194', 'de', 'Achisch von Gat'),
('925ca864-222a-e950-020f-8630cb54f194', 'en', 'Achish of Gath'),
('c509014d-0441-af98-99d9-8c9409234332', 'de', 'Jonatan, Sauls Sohn'),
('c509014d-0441-af98-99d9-8c9409234332', 'en', 'Jonathan, Saul''s son'),
('2781eaea-80ae-a117-51f2-2127df15ef74', 'de', 'Abner, den Heerführer Sauls'),
('2781eaea-80ae-a117-51f2-2127df15ef74', 'en', 'Abner, Saul''s army commander'),
('2d83860e-ef3b-5c6a-830e-ef160cb85903', 'de', 'Sie werden Lieder dichten'),
('2d83860e-ef3b-5c6a-830e-ef160cb85903', 'en', 'They will compose songs'),
('5474880c-5ecb-d833-6acf-95e4ff48b662', 'de', 'Sie werden weissagen'),
('5474880c-5ecb-d833-6acf-95e4ff48b662', 'en', 'They will prophesy'),
('49e95eca-0387-743c-5a25-91bb6a9f0a6a', 'de', 'Sie werden nach Babylon ziehen'),
('49e95eca-0387-743c-5a25-91bb6a9f0a6a', 'en', 'They will go to Babylon'),
('59c7f0e8-fafe-c626-ae12-8d7217ef28ca', 'de', 'Sie werden den Tempel bewachen'),
('59c7f0e8-fafe-c626-ae12-8d7217ef28ca', 'en', 'They will guard the temple'),
