('0c58306d-98b0-5e63-6432-8ee5c4b74ce6', 'en', 'Twelve'),
('1efe0905-3df7-c6da-a856-0340f7f844b2', 'de', 'Hundertdreiundfünfzig'),
('1efe0905-3df7-c6da-a856-0340f7f844b2', 'en', 'A hundred and fifty-three'),
('ec18b19b-2245-13cf-3bd9-a2200c029635', 'de', 'Fünfzig'),
('ec18b19b-2245-13cf-3bd9-a2200c029635', 'en', 'Fifty'),
('b9ddcddd-a73b-e4fb-2de2-7a11d3678419', 'de', 'Hundert'),
('b9ddcddd-a73b-e4fb-2de2-7a11d3678419', 'en', 'A hundred'),
