('f9d46a66-215f-e663-b0e6-c8aa7ea0d188', 'en', 'Cleansed in the tears of repentance'),
('87d18afb-1872-b9b4-c6fe-067c2fb50808', 'de', 'Sie wurde aus dem Lager verbannt für immer'),
('87d18afb-1872-b9b4-c6fe-067c2fb50808', 'en', 'She was banished from the camp forever'),
('151abfd3-218a-4d82-5848-187c48210cb6', 'de', 'Die Erde verschlang sie'),
('151abfd3-218a-4d82-5848-187c48210cb6', 'en', 'The earth swallowed her'),
