('30c46632-f469-3145-e3d0-c0ceaa3cf9da', 'en', 'Three baskets full'),
('7d02af7b-948a-f028-e604-8d632a9e8b23', 'de', 'Sieben Körbe voll'),
('7d02af7b-948a-f028-e604-8d632a9e8b23', 'en', 'Seven baskets full'),
('923c942e-5dad-820a-84ec-9faf7a98783f', 'de', 'Fünf Körbe voll'),
('923c942e-5dad-820a-84ec-9faf7a98783f', 'en', 'Five baskets full'),
