('860296cf-3145-2fc6-4e5b-565f334a0fac', 'en', 'Jonathan, Abinadab and Malchishua'),
('da61a399-5614-aa8e-03f5-397ca81b377f', 'de', 'Isch-Boschet und Abner'),
('da61a399-5614-aa8e-03f5-397ca81b377f', 'en', 'Ish-bosheth and Abner'),
('120b896d-a57b-f989-7103-0005ec2451eb', 'de', 'David und Jonatan'),
('120b896d-a57b-f989-7103-0005ec2451eb', 'en', 'David and Jonathan'),
('6770f1a8-56d6-755d-5a29-59d84a14a2ad', 'de', 'Sie freut sich über die Ungerechtigkeit'),
('6770f1a8-56d6-755d-5a29-59d84a14a2ad', 'en', 'It rejoices in wrongdoing'),
