('52d21bea-25c9-d1e9-7efe-1c2f8f990f3f', 'en', 'The tribe of Benjamin'),
('11fd50b1-42d8-d959-2fb6-38a1a5f5912e', 'de', 'Die Leviten'),
('11fd50b1-42d8-d959-2fb6-38a1a5f5912e', 'en', 'The Levites'),
('e009f2a1-7d54-d739-6928-642fe30f84cf', 'de', 'Die Söhne Judas'),
('e009f2a1-7d54-d739-6928-642fe30f84cf', 'en', 'The sons of Judah'),
('80d11185-e45f-fc38-0cbf-d512c2ee41e7', 'de', 'Der Stamm Ruben'),
('80d11185-e45f-fc38-0cbf-d512c2ee41e7', 'en', 'The tribe of Reuben'),
