('b8cd8f97-e0a2-9b69-566c-7fa14567e340', 'en', 'The mother-in-law of James'),
('b69fdaec-fbe0-aed7-f497-dc2be54884f2', 'de', 'Die Schwiegermutter des Johannes'),
('b69fdaec-fbe0-aed7-f497-dc2be54884f2', 'en', 'The mother-in-law of John'),
('94c858db-e949-c71c-858a-b5296d2cb0ce', 'de', 'Die Schwiegermutter des Petrus'),
('94c858db-e949-c71c-858a-b5296d2cb0ce', 'en', 'The mother-in-law of Peter'),
('fc06d479-f8f1-e7d5-d5c1-16ee63da19e2', 'de', 'Die Schwiegermutter des Andreas'),
('fc06d479-f8f1-e7d5-d5c1-16ee63da19e2', 'en', 'The mother-in-law of Andrew'),
('0b8e829a-117b-2442-f38d-de09ce6fa00a', 'de', 'Ich verberge deine Übertretungen und schweige über deine Sünden'),
('0b8e829a-117b-2442-f38d-de09ce6fa00a', 'en', 'I hide your transgressions and stay silent about your sins'),
