('162bdc83-fc86-29c2-309e-172e63bb3378', 'en', 'For the gardener'),
('f0547296-ca10-1fd6-ee6e-91bab8e2abb4', 'de', 'Für einen Engel'),
('f0547296-ca10-1fd6-ee6e-91bab8e2abb4', 'en', 'For an angel'),
('c8e5794c-dfc0-f6cb-e977-014f6c651867', 'de', 'Für einen römischen Soldaten'),
('c8e5794c-dfc0-f6cb-e977-014f6c651867', 'en', 'For a Roman soldier'),
('39e8bfb6-a6c0-f11b-4abc-73ba68ddf09b', 'de', 'Für den Hohenpriester'),
('39e8bfb6-a6c0-f11b-4abc-73ba68ddf09b', 'en', 'For the high priest'),
('9197e0c6-7e37-d0cc-4177-2a788e846b73', 'de', 'Wie ein Sturm vom Meer her'),
('9197e0c6-7e37-d0cc-4177-2a788e846b73', 'en', 'Like a storm from the sea'),
