('d2e3f90c-9825-9305-d23a-058a1b513084', 'en', 'With gold and silver'),
('0b60cd9b-2ba5-d910-a955-486453dea36f', 'de', 'Als er in den Krieg zog'),
('0b60cd9b-2ba5-d910-a955-486453dea36f', 'en', 'While going to war'),
('25044e4a-a796-2734-2840-03a48fa83a0b', 'de', 'Als er Schafe weidete'),
('25044e4a-a796-2734-2840-03a48fa83a0b', 'en', 'While tending sheep'),
