('9d075464-bfc6-d30e-6822-28b6c432d28d', 'en', 'The blood of a dove'),
('de77b2ad-7f85-1814-231f-ca92bfe223a5', 'de', 'Fürchtest du dich?'),
('de77b2ad-7f85-1814-231f-ca92bfe223a5', 'en', 'Are you afraid?'),
('8a70544a-d62c-5745-6bee-88b2f6862c59', 'de', 'Willst du mir folgen?'),
('8a70544a-d62c-5745-6bee-88b2f6862c59', 'en', 'Will you follow me?'),
('7ab28016-2e2f-5389-d06f-cecd9a8a30c5', 'de', 'Glaubst du an mich?'),
('7ab28016-2e2f-5389-d06f-cecd9a8a30c5', 'en', 'Do you believe in me?'),
('11cfff41-1d52-3e77-a345-6f45185b723c', 'de', 'Hast du mich lieb?'),
('11cfff41-1d52-3e77-a345-6f45185b723c', 'en', 'Do you love me?'),
('fdab0228-5265-c5dd-d795-7d4092e8dec0', 'de', 'Auf die Pfeiler des Altars'),
('fdab0228-5265-c5dd-d795-7d4092e8dec0', 'en', 'On the columns of the altar'),
('af99e7aa-d095-de8b-6150-b56bcd360460', 'de', 'Auf die Stützen der Empore'),
('af99e7aa-d095-de8b-6150-b56bcd360460', 'en', 'On the supports of the gallery'),
