('aab3d315-8650-9be4-8ffa-d534cf4500eb', 'en', 'Go and do likewise'),
('9a75ac5b-83b4-5c7a-3d64-e9d97e316718', 'de', 'Schweige und bete im Verborgenen'),
('9a75ac5b-83b4-5c7a-3d64-e9d97e316718', 'en', 'Be silent and pray in secret'),
('5488cd45-d2c9-9af8-7e23-8a9081626df8', 'de', 'Verkaufe alles, was du hast'),
('5488cd45-d2c9-9af8-7e23-8a9081626df8', 'en', 'Sell everything you have'),
