('8a9ae7af-47b3-17c2-50c7-85691482b4f2', 'en', 'The brother of two sisters'),
('c8500d5a-9664-0ffa-acc4-694016010235', 'de', 'Einen jungen Schriftgelehrten'),
('c8500d5a-9664-0ffa-acc4-694016010235', 'en', 'A young scribe'),
('ce042bef-1f2a-6ffa-c71e-7e0f1f5632aa', 'de', 'Den einzigen Sohn einer Witwe'),
('ce042bef-1f2a-6ffa-c71e-7e0f1f5632aa', 'en', 'The only son of a widow'),
('19c14a21-2859-1770-deac-a981048292e7', 'de', 'Weil sie Hiobs Reichtum begehrten'),
('19c14a21-2859-1770-deac-a981048292e7', 'en', 'Because they coveted Job''s wealth'),
('3c03f06f-20a0-f5d9-88af-f1e9715cb21c', 'de', 'Weil sie Gott gelästert hatten'),
('3c03f06f-20a0-f5d9-88af-f1e9715cb21c', 'en', 'Because they had blasphemed God'),
