('06d3ea2e-41e4-fd2a-8c61-49450faa9ab6', 'en', 'Against the Philistines'),
('e6659e10-04bf-b9a7-54e9-868acdfdf696', 'de', 'Gegen Moab'),
('e6659e10-04bf-b9a7-54e9-868acdfdf696', 'en', 'Against Moab'),
('d555a01f-405e-11e7-d66c-ee1a3b73a2a6', 'de', 'Gegen Edom'),
('d555a01f-405e-11e7-d66c-ee1a3b73a2a6', 'en', 'Against Edom'),
