('960c2071-50c2-d951-a236-53616e4f8eff', 'en', 'He was at once proclaimed king'),
('247a6791-ac37-a5a6-e126-9f6c3cb442f9', 'de', 'Er floh aus seiner Heimat'),
('247a6791-ac37-a5a6-e126-9f6c3cb442f9', 'en', 'He fled from his homeland'),
('a33f0908-5f40-e931-eb58-04e24d226c7b', 'de', 'Zweifelte nicht unser Herz an seinen Worten?'),
('a33f0908-5f40-e931-eb58-04e24d226c7b', 'en', 'Did not our hearts doubt his words?'),
('0811a750-971f-be63-987e-cfc9efed3678', 'de', 'Wurde nicht unser Herz schwer vor Trauer?'),
('0811a750-971f-be63-987e-cfc9efed3678', 'en', 'Did not our hearts grow heavy with grief?'),
('4718c42a-9b03-531e-7697-ae9befc0d8ef', 'de', 'Brannte nicht unser Herz in uns, als er mit uns redete?'),
('4718c42a-9b03-531e-7697-ae9befc0d8ef', 'en', 'Did not our hearts burn within us as he spoke?'),
('9c7fca03-59e9-8ade-bc02-d391cf0f9251', 'de', 'Erschrak nicht unser Herz vor dem Fremden?'),
('9c7fca03-59e9-8ade-bc02-d391cf0f9251', 'en', 'Did not our hearts fear the stranger?'),
