('c7270a1d-e20e-b75e-fb89-6117e81d467b', 'en', 'She would be weeping at the well'),
('68cab21a-ad0e-63ad-f61d-a058201d6b2b', 'de', 'Ruben und Gad'),
('68cab21a-ad0e-63ad-f61d-a058201d6b2b', 'en', 'Reuben and Gad'),
