('15093064-c54c-36a9-479f-761ff7658f4d', 'en', 'Judah and Benjamin'),
('36f4d613-7544-8ed7-d0ee-aa5fbc602e8b', 'de', 'Ephraim und Manasse'),
('36f4d613-7544-8ed7-d0ee-aa5fbc602e8b', 'en', 'Ephraim and Manasseh'),
