('1498357f-8654-0aea-2145-49d9bdbcf79f', 'en', 'Your kingdom is divided'),
('2569533a-93b9-6ff1-a9ee-0d7462bd50b2', 'de', 'Allen Reichtum und irdischen Besitz'),
('2569533a-93b9-6ff1-a9ee-0d7462bd50b2', 'en', 'All wealth and earthly possessions'),
('122fda7c-9b8d-0600-9069-c811c3c9d62a', 'de', 'Alle Worte und jegliches Schweigen'),
('122fda7c-9b8d-0600-9069-c811c3c9d62a', 'en', 'All words and any silence'),
('088b1546-bf56-509d-1769-38b2dbcf1baa', 'de', 'Alle Last und die Sünde, die uns umstrickt'),
('088b1546-bf56-509d-1769-38b2dbcf1baa', 'en', 'Every weight and the sin that entangles us'),
('a504014e-d51a-b1ef-c11b-2944853d122a', 'de', 'Alle Furcht vor dem kommenden Gericht'),
('a504014e-d51a-b1ef-c11b-2944853d122a', 'en', 'All fear of the coming judgment'),
('2e9ad027-5921-4af6-8f02-e682a9c44398', 'de', 'Achisch verbot es ihm'),
('2e9ad027-5921-4af6-8f02-e682a9c44398', 'en', 'Achish forbade it'),
('90882200-314d-ee8f-922f-4cdfae3f1520', 'de', 'Die Philisterfürsten misstrauten ihm und schickten ihn zurück'),
('90882200-314d-ee8f-922f-4cdfae3f1520', 'en', 'The Philistine lords distrusted him and sent him back'),
('bb12f4bc-fd0b-ca0a-46d1-a804aa8db971', 'de', 'Er war im Land Juda gebunden'),
('bb12f4bc-fd0b-ca0a-46d1-a804aa8db971', 'en', 'He was bound in the land of Judah'),
('2965c986-5672-2483-8d47-57055af0bb24', 'de', 'Saul hatte ihn dazu aufgefordert'),
('2965c986-5672-2483-8d47-57055af0bb24', 'en', 'Saul had summoned him'),
('875ce042-9523-50ef-2465-d748efda7ef6', 'de', 'Aus Akazienholz'),
('875ce042-9523-50ef-2465-d748efda7ef6', 'en', 'Of acacia wood'),
('b1ae4d42-0100-f8ca-c39d-2bc0b026c01f', 'de', 'Aus geschlagenem Stein'),
('b1ae4d42-0100-f8ca-c39d-2bc0b026c01f', 'en', 'Of hewn stone'),
('d08fe674-698c-b05a-be24-2d09d602479d', 'de', 'Aus Zedern vom Libanon'),
('d08fe674-698c-b05a-be24-2d09d602479d', 'en', 'Of cedars from Lebanon'),
('df0dc968-0b89-e9a9-b72a-9188b3181006', 'de', 'Aus Gopherholz'),
('df0dc968-0b89-e9a9-b72a-9188b3181006', 'en', 'Of gopher wood'),
('23804307-140e-bb0b-8dee-e6081b69fab8', 'de', 'Der Arme bestahl den Reichen um seine Herde'),
('23804307-140e-bb0b-8dee-e6081b69fab8', 'en', 'The poor man robbed the rich man of his flock'),
