('f4dc3379-9cfe-6db3-46c5-7ee7f4a3f2ff', 'en', 'With ten thousand remaining men'),
('2c5c7ea7-fc0a-cfb9-32cf-1c05f9b3e48f', 'de', 'Mit zweiunddreißigtausend Mann'),
('2c5c7ea7-fc0a-cfb9-32cf-1c05f9b3e48f', 'en', 'With thirty-two thousand men'),
('554e0803-e952-89c1-bf5b-6083957ce335', 'de', 'Mit dreitausend erlesenen Kriegern'),
('554e0803-e952-89c1-bf5b-6083957ce335', 'en', 'With three thousand chosen warriors'),
