('7f3d5cce-0286-472d-84f2-bc3a71a74666', 'en', 'Thomas and Philip'),
('e982709b-b116-d860-7728-838728939438', 'de', 'Jakobus und Johannes'),
('e982709b-b116-d860-7728-838728939438', 'en', 'James and John'),
('8441f1a3-d377-5f65-e911-ede60681692c', 'de', 'Petrus und der Jünger, den Jesus lieb hatte'),
('8441f1a3-d377-5f65-e911-ede60681692c', 'en', 'Peter and the disciple whom Jesus loved'),
('e5b4517c-3401-fed4-f2ad-b16100f6800d', 'de', 'Andreas und Nathanael'),
('e5b4517c-3401-fed4-f2ad-b16100f6800d', 'en', 'Andrew and Nathanael'),
