('98636832-bde3-dd60-7351-cbd59bb81e5f', 'en', '… hidden in my house'),
('f5b90f04-f626-549c-8796-be42e5900a72', 'de', '… draußen auf dem Weg'),
('f5b90f04-f626-549c-8796-be42e5900a72', 'en', '… outside on the road'),
('69fb6408-7135-7c18-5807-a2dd6f80290d', 'de', '… hinter meinem Feld'),
('69fb6408-7135-7c18-5807-a2dd6f80290d', 'en', '… behind my field'),
('3d1053c6-c79f-d3db-f68d-2ee0216c4437', 'de', '… an meiner Tür'),
('3d1053c6-c79f-d3db-f68d-2ee0216c4437', 'en', '… at my door'),
