('3cb8dbfc-4901-63f4-62c4-96fded363ecd', 'en', 'He wept in remorse'),
('6d158d13-0048-fd8f-dcfb-2f0a3ec81db7', 'de', 'Er fiel ohnmächtig zu Boden'),
('6d158d13-0048-fd8f-dcfb-2f0a3ec81db7', 'en', 'He fell down in a faint'),
