('9103c2c0-f8b8-346d-811d-0638cedf7da1', 'en', 'In the open by the oak of Mamre'),
('5375f885-f78c-d303-655f-1d58c4c210b2', 'de', 'In einem Grab in Ägypten'),
('5375f885-f78c-d303-655f-1d58c4c210b2', 'en', 'In a tomb in Egypt'),
('da2b4e78-8f24-ce75-a722-bc1afc73556f', 'de', 'In Abrahams Schoß'),
('da2b4e78-8f24-ce75-a722-bc1afc73556f', 'en', 'Into Abraham''s bosom'),
('36eaf2c5-7f8e-a0ff-9251-f4e62a5f04e6', 'de', 'In das Reich des Reichen'),
('36eaf2c5-7f8e-a0ff-9251-f4e62a5f04e6', 'en', 'Into the realm of the rich man'),
