('83a6d5fd-38c5-88f1-b6e2-cf7f23dae532', 'en', 'Protection for one who had killed unintentionally'),
('1b07a31e-58bd-56aa-5585-cb9b52fb795c', 'de', 'Aufbewahrungsorte für den Zehnten'),
('1b07a31e-58bd-56aa-5585-cb9b52fb795c', 'en', 'Storage for the tithe'),
('0f324c02-596e-8a06-b599-95abae451ca4', 'de', 'Wohnungen für die Fremden'),
