('90670805-69da-b53c-338b-a7d35d6c8c53', 'en', 'Immediate return to the sanctuary'),
('b428f353-749d-b678-4dff-eff63bd0153e', 'de', 'Vierzig Tage Fasten ohne Wasser'),
('b428f353-749d-b678-4dff-eff63bd0153e', 'en', 'Forty days of fasting without water'),
('6957eff2-84f9-9168-559e-ad8a9ef141a3', 'de', 'Ein Brandopfer am selben Tag'),
('6957eff2-84f9-9168-559e-ad8a9ef141a3', 'en', 'A burnt offering on the same day'),
('fabb7b68-b54d-fda2-e2bd-c35d0ba2d91e', 'de', 'Er erblindete für sieben Jahre'),
('fabb7b68-b54d-fda2-e2bd-c35d0ba2d91e', 'en', 'He went blind for seven years'),
('9b9e3e9e-20aa-05f1-633e-11e017466a2a', 'de', 'Er verfiel in tiefen Schlaf'),
('9b9e3e9e-20aa-05f1-633e-11e017466a2a', 'en', 'He fell into a deep sleep'),
