('06ad80d8-929a-0699-9235-81a87de6c33f', 'en', 'At the city gate before ten elders of the city'),
('c5520163-2306-c843-dfcf-c78e106fe9d8', 'de', 'Auf dem Feld bei der Ernte'),
('c5520163-2306-c843-dfcf-c78e106fe9d8', 'en', 'In the field during the harvest'),
('ef57c874-d278-14c5-0999-48dc9d7f990d', 'de', 'Im Haus der Noomi'),
('ef57c874-d278-14c5-0999-48dc9d7f990d', 'en', 'In the house of Naomi'),
('eeada01c-3a82-e47c-ada5-efa23435c22a', 'de', 'Der Hirte und Hüter der Seelen'),
('eeada01c-3a82-e47c-ada5-efa23435c22a', 'en', 'The shepherd and guardian of souls'),
('b3ca1ee8-c01d-0fb0-4119-f2560ef15a17', 'de', 'Der Anfänger und Vollender des Glaubens'),
('b3ca1ee8-c01d-0fb0-4119-f2560ef15a17', 'en', 'The author and finisher of faith'),
