('e9b84167-a9ba-9e2c-0215-08b455d6e34e', 'en', 'The laws about the festival of Purim'),
('693a1983-7215-e561-9ae6-375f11ea525e', 'de', 'Den Erlass Hamans gegen die Juden'),
('693a1983-7215-e561-9ae6-375f11ea525e', 'en', 'Haman''s decree against the Jews'),
('c311c586-a151-5796-1e35-872ea374393b', 'de', 'Die Liste der Geschenke an Esther'),
('c311c586-a151-5796-1e35-872ea374393b', 'en', 'The list of gifts given to Esther'),
('98604af8-0a47-f0c5-d0c7-a148e65f3fb2', 'de', 'Die Chronik, worin Mordechais Rettungstat stand'),
('98604af8-0a47-f0c5-d0c7-a148e65f3fb2', 'en', 'The chronicle in which Mordecai''s deed of rescue stood'),
('d672b1ab-f7a0-6626-44bb-ec9136fba072', 'de', 'Geradewegs nach Ägypten zu ziehen'),
('d672b1ab-f7a0-6626-44bb-ec9136fba072', 'en', 'To go straight to Egypt'),
('85ded04a-9aaf-33b0-e099-6092c07d4247', 'de', 'Ihr Vieh mitzunehmen'),
('85ded04a-9aaf-33b0-e099-6092c07d4247', 'en', 'To take their livestock with them'),
