('07bb63f3-c8cb-a758-c40f-29283b35d62b', 'en', 'To wait at the city gate'),
('5373dd47-6ded-98de-1536-5c2db89aeed8', 'de', 'Nicht zurückzuschauen und nicht stehenzubleiben'),
('5373dd47-6ded-98de-1536-5c2db89aeed8', 'en', 'Not to look back and not to stop'),
('9ca0ccc6-5e1b-de0e-ac97-9e3688618ef0', 'de', 'In seinem Reichtum'),
('9ca0ccc6-5e1b-de0e-ac97-9e3688618ef0', 'en', 'In his wealth'),
('420c6930-cedc-bc92-30ac-6deb53fb7559', 'de', 'In seiner Herkunft'),
('420c6930-cedc-bc92-30ac-6deb53fb7559', 'en', 'In his ancestry'),
('4a7dadee-a67b-876b-eef2-0a809eaad6d6', 'de', 'In seinem Familienleben'),
('4a7dadee-a67b-876b-eef2-0a809eaad6d6', 'en', 'In his family life'),
