('a3263290-c716-ad97-b4c5-05a32db95f71', 'en', 'Only a gravestone in Jezreel'),
('472e7eff-34d8-1d3f-9f55-ee63f4599c00', 'de', 'Nur ihre königlichen Gewänder'),
('472e7eff-34d8-1d3f-9f55-ee63f4599c00', 'en', 'Only her royal garments'),
('4a800604-7e0e-45b5-791c-087467144ca4', 'de', 'Nur Schädel, Füße und Hände'),
('4a800604-7e0e-45b5-791c-087467144ca4', 'en', 'Only the skull, the feet, and the hands'),
