('85ecd71f-3517-6410-e292-8c52e6ad3886', 'en', 'A bull and a dragon'),
('6229c98f-82a2-fac2-09cf-a020eb200715', 'de', 'Einen Löwen und einen Bären'),
('6229c98f-82a2-fac2-09cf-a020eb200715', 'en', 'A lion and a bear'),
('a8042016-7a86-5a45-47d5-073bade65965', 'de', 'Einen Leoparden und einen Adler'),
('a8042016-7a86-5a45-47d5-073bade65965', 'en', 'A leopard and an eagle'),
