('95e2c354-7639-c984-6890-a7e0b63b4b08', 'en', 'A Samaritan'),
('715a8106-07eb-7b84-d30c-a5a2321b73f7', 'de', 'Ein römischer Soldat'),
('715a8106-07eb-7b84-d30c-a5a2321b73f7', 'en', 'A Roman soldier'),
('c1d870c8-61a3-9f3b-bcd0-2563a049ccb8', 'de', 'Ein Pharisäer'),
('c1d870c8-61a3-9f3b-bcd0-2563a049ccb8', 'en', 'A Pharisee'),
('578c1a1a-73e3-18fb-d8ea-7a50d275acf8', 'de', 'Sie gaben sich als Brüder Israels aus'),
('578c1a1a-73e3-18fb-d8ea-7a50d275acf8', 'en', 'They claimed to be brothers of Israel'),
