('ac7f68a9-8715-863e-3646-99e7ef251013', 'en', 'Throw himself to the ground'),
('53f59bca-374d-a92d-5c03-4e9162a3d3c9', 'de', 'Seinen Stab niederlegen'),
('53f59bca-374d-a92d-5c03-4e9162a3d3c9', 'en', 'Lay down his staff'),
('a49985ca-cde2-de67-a1c5-b445b0b6b98e', 'de', 'Ein Opfer darbringen'),
('a49985ca-cde2-de67-a1c5-b445b0b6b98e', 'en', 'Offer a sacrifice'),
('85a80f56-f218-116b-f437-f66dbebfef0e', 'de', 'Seine Schuhe von den Füßen ziehen'),
('85a80f56-f218-116b-f437-f66dbebfef0e', 'en', 'Take the sandals off his feet'),
