('94ec637a-93b9-41ea-d2d4-7909076161a9', 'en', 'Not to mix with them and serve their gods'),
('0430f0ff-5154-85b3-8e7c-d542d22190fa', 'de', 'Die Frauen mit wohlriechenden Salben'),
('0430f0ff-5154-85b3-8e7c-d542d22190fa', 'en', 'The women with fragrant spices'),
('97f0b75a-e463-cdf8-9b71-46aad00d9057', 'de', 'Die Hohenpriester mit der Tempelwache'),
('97f0b75a-e463-cdf8-9b71-46aad00d9057', 'en', 'The chief priests with the temple guard'),
('6ed49914-1480-61a6-b7d4-e605474deeb4', 'de', 'Die römischen Soldaten'),
('6ed49914-1480-61a6-b7d4-e605474deeb4', 'en', 'The Roman soldiers'),
